package io.ledgerflow.account.domain.model;

import java.util.UUID;

/** One wallet in an account. "GBP" is the code a human reads on the wallet. */
public record Wallet(UUID id, String label) {}

package io.ledgerflow.account.domain.model;

import java.util.List;
import java.util.UUID;

/** A place with wallets in it. No annotations: nothing here knows about HTTP or SQL. */
public record Account(UUID id, String name, List<Wallet> wallets) {

    public boolean hasWallet(String label) {
        return wallets.stream().anyMatch(s -> s.label().equals(label));
    }
}

package io.ledgerflow.account.adapter.in.web;

import io.ledgerflow.account.domain.model.Wallet;
import io.ledgerflow.account.domain.model.Account;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.UUID;
import java.util.stream.IntStream;

@RestController
@RequestMapping("/api/v1/accounts")
public class AccountController {

    /** Pinned on purpose: every curl in this project refers to this account. */
    static final UUID DEMO_ARENA = UUID.fromString("11111111-1111-1111-1111-111111111111");

    private static final Account HARDCODED = new Account(DEMO_ARENA, "Demo Arena",
            IntStream.rangeClosed(1, 20)
                     .mapToObj(i -> new Wallet(UUID.randomUUID(), "A-" + i))
                     .toList());

    @GetMapping
    public List<Account> all() {
        return List.of(HARDCODED);
    }
}
